works","description":"Coordinates grain shipments and quiet supply routes across the isles.","category":"social"}]}],"relationships":[{"id":"rel_valeria_vane_enemy","source_character_id":"chr_valeria_corvane","target_character_id":"chr_brennick_vane","relationship_type":"enemy","description":"Valeria Corvane schemes to dismantle Brennick Vane's rise, and he treats her as the discredited elite he rallies crowds against."},{"id":"rel_vane_valeria_enemy","source_character_id":"chr_brennick_vane","target_character_id":"chr_valeria_corvane","relationship_type":"enemy","description":"Brennick Vane sees Valeria Corvane as the chief obstacle to emergency powers and moves to ruin her through his followers."},{"id":"rel_valeria_tomas_ally","source_character_id":"chr_valeria_corvane","target_character_id":"chr_tomas_reeve","relationship_type":"ally","description":"Valeria Corvane uses Tomas Reeve as a source inside the Wardens, exploiting his trust while he believes she is a mentor."},{"id":"rel_valeria_odalys_ally","source_character_id":"chr_valeria_corvane","target_character_id":"chr_odalys_marrin","relationship_type":"ally","description":"Valeria Corvane seeks Odalys Marrin's grain records as evidence, and Odalys cautiously weighs the alliance."},{"id":"rel_odalys_vane_rival","source_character_id":"chr_odalys_marrin","target_character_id":"chr_brennick_vane","relationship_type":"rival","description":"Odalys Marrin resists the Grain Levy that Brennick Vane enforces for the Cartel, putting her at odds with him."}]}
