er_id":"chr_maren_voss","target_character_id":"chr_corvin_hale","relationship_type":"rival","description":"Maren Voss blames Corvin Hale's rising tolls for starving the Wardens of repair funds, and Corvin sees her warnings as a threat to his trade."},{"id":"rel_isolde_maren_mentor","source_character_id":"chr_isolde_penn","target_character_id":"chr_maren_voss","relationship_type":"mentor","description":"Isolde Penn looks to Maren Voss for field knowledge to ground her charts, while Maren is reluctantly drawn to Isolde's data."},{"id":"rel_tobiah_corvin_enemy","source_character_id":"chr_tobiah_marsh","target_character_id":"chr_corvin_hale","relationship_type":"enemy","description":"Tobiah Marsh opposes Corvin Hale's grain levy, which threatens the Hollow's farmers."},{"id":"rel_maren_tobiah_ally","source_character_id":"chr_maren_voss","target_character_id":"chr_tobiah_marsh","relationship_type":"ally","description":"Maren Voss and Tobiah Marsh become allies against the Cartel, trading bridge repairs for grain."}]}
